export const mockCategoryHierarchy: Record<string, CategoryWithHierarchy> = {};

mockCategories.forEach(category => {
  const subcategories: SubcategoryWithGroups[] = mockSubcategories
      .filter(sub => sub.categoryId === category.id)
      .map(sub => ({
        ...sub,
        groups: mockGroups.filter(g => g.subcategoryId === sub.id),
      }));

  mockCategoryHierarchy[category.slug] = {
    ...category,
    subcategories,
  };
});
